import{_ as o,o as a,c as r,ae as i}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"Cambios de comportamiento por defecto y de plataforma","description":"","frontmatter":{},"headers":[],"relativePath":"es/explanation/modificaciones-motor/09-cambios-de-comportamiento.md","filePath":"es/explanation/modificaciones-motor/09-cambios-de-comportamiento.md"}'),n={name:"es/explanation/modificaciones-motor/09-cambios-de-comportamiento.md"};function t(c,e,l,d,s,m){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="cambios-de-comportamiento-por-defecto-y-de-plataforma" tabindex="-1">Cambios de comportamiento por defecto y de plataforma <a class="header-anchor" href="#cambios-de-comportamiento-por-defecto-y-de-plataforma" aria-label="Permalink to &quot;Cambios de comportamiento por defecto y de plataforma&quot;">​</a></h1><h2 id="cambios-de-comportamiento" tabindex="-1">Cambios de comportamiento <a class="header-anchor" href="#cambios-de-comportamiento" aria-label="Permalink to &quot;Cambios de comportamiento&quot;">​</a></h2><p>Además de las extensiones funcionales, el motor introduce cambios de comportamiento que conviene conocer:</p><ul><li><strong>Paso de tiempo variable por defecto</strong>: <code>VARIABLE_STEP</code> por defecto es <strong>0.75</strong> (paso adaptativo por Courant), mientras que el manual del SWMM 5.x documenta 0 (paso fijo). Para reproducir el comportamiento del SWMM oficial debe fijarse <code>VARIABLE_STEP 0</code>.</li><li><strong>Manejo de unidades de las tolerancias</strong>: la <code>HEAD_TOLERANCE</code> y el <code>MIN_SURFAREA</code> se convierten desde las unidades del proyecto al sistema interno (pies) al inicializar, corrigiendo errores de factor 3.3–10.8 en modelos SI del motor anterior.</li><li><strong>Pérdidas de conducto por iteración</strong>: bajo onda dinámica, la evaporación y filtración de conductos se recalculan en <em>cada</em> iteración de Picard (con la compuerta de clase de escurrimiento), igual que el motor legado, en lugar de una vez por paso.</li><li><strong>Recuento de convergencia</strong>: un paso que converge en su último intento permitido se cuenta como convergido (solo falla si no converge tras <code>MAX_TRIALS</code>).</li><li><strong>Salto de estado estacionario</strong>: <code>SKIP_STEADY_STATE</code> omite el tránsito cuando no hubo acciones de control, el error de continuidad está bajo la tolerancia y los aportes no cambiaron.</li></ul><h2 id="extensiones-de-plataforma-y-formato" tabindex="-1">Extensiones de plataforma y formato <a class="header-anchor" href="#extensiones-de-plataforma-y-formato" aria-label="Permalink to &quot;Extensiones de plataforma y formato&quot;">​</a></h2><ul><li><strong>CRS</strong>: la opción <code>CRS</code> en <code>[OPTIONS]</code> acepta un EPSG o una cadena PROJ, transportando el sistema de referencia espacial del modelo (el SWMM oficial no la posee).</li><li><strong>Claves de extensión</strong>: <code>ext_options</code> almacena cualquier clave desconocida de <code>[OPTIONS]</code> para plugins.</li><li><strong>IGNORE_2D</strong>: permite desactivar el solver 2D conservando la malla en el archivo (para ejecutar el modelo solo 1D).</li><li><strong>Geopackage</strong>: entrada/salida nativa en GeoPackage (incluida la tabla <code>rdii_decay</code> de los parámetros de recuperación), además del formato <code>.inp</code>.</li><li><strong>API C</strong>: una API en C (con envoltorios) expone todas las extensiones (por ejemplo <code>swmm_rdii_decay_add</code>).</li><li><strong>WebAssembly</strong>: el motor se compila a WASM para ejecutarse en el navegador (como usa LocalSWMM), con el solver 2D en GPU/WebGPU.</li><li><strong>Pruebas de soluciones manufacturadas</strong>: el repositorio incluye una batería de benchmarks con soluciones analíticas (rotura de presa de Ritter, lago en reposo, ondas de Macdonald, curvas de referencia de impulsiones, entre otras) que anclan la fidelidad de los solvers.</li></ul><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;Referencias&quot;">​</a></h2><ol><li>Rossman, L. A. (2017). <em>Storm Water Management Model Reference Manual Volume II — Hydraulics</em>. U.S. EPA.</li><li>Sharior, S., Hodges, B. R., &amp; Vasconcelos, J. G. (2023). Generalized, dynamic, and transient-storage form of the Preissmann slot. <em>Journal of Hydraulic Engineering</em>, 149(11).</li><li>de Almeida, G. A. M., &amp; Bates, P. D. (2013). Applicability of the local inertial approximation of the shallow water equations to flood modeling. <em>Water Resources Research</em>, 49(8).</li><li>Código fuente del motor OpenSWMM (HydroCouple): <ul><li><code>src/engine/hydraulics/DynamicWave.cpp</code>, <code>src/engine/hydraulics/HydStructures.cpp</code>, <code>src/engine/hydraulics/fv/ExplicitFvSolver.cpp</code></li><li><code>src/engine/2d/</code> (marchante y acople), <code>src/engine/hydrology/RDII.cpp</code>, <code>src/engine/core/SimulationOptions.hpp</code></li></ul></li><li>Manuales de referencia del motor OpenSWMM (Vol. II — Hydraulics, cap. 3, 7, 9; Vol. I — Hydrology, cap. 7).</li></ol>',8)])])}const f=o(n,[["render",t]]);export{u as __pageData,f as default};
